		var openEvent:Event = new Event(Event.OPEN);
		contentLoaderInfo.dispatchEvent(openEvent);

		contentLoaderInfo.loaderURL = Lib.current.loaderInfo.url;
		contentLoaderInfo.url = request.url;
		__unloaded = false;

		if (request.contentType == null || request.contentType == "")
		{
			var extension = "";
			var path = request.url;

			var queryIndex = path.indexOf("?");
			if (queryIndex > -1)
			{
				path = path.substring(0, queryIndex);
			}

			while (StringTools.endsWith(path, "/"))
			{
				path = path.substring(0, path.length - 1);
			}

			if (StringTools.endsWith(path, ".bundle"))
			{
				path += "/library.json";

				if (queryIndex > -1)
				{
					request.url = path + request.url.substring(queryIndex);
				}
				else
				{
					request.url = path;
				}
			}

			var extIndex = path.lastIndexOf(".");
			if (extIndex > -1)
			{
				extension = path.substring(extIndex + 1);
			}

			contentLoaderInfo.contentType = switch (extension)
			{
				case "json": "application/json";
				case "swf": "application/x-shockwave-flash";
				case "jpg", "jpeg": "image/jpeg";
				case "png": "image/png";
				case "gif": "image/gif";
				case "js": "application/javascript";
