		{
			display.removeEventListener(Event.UNLOAD, display_onUnload);

			if (display.parent == Lib.current)
			{
				Lib.current.removeChild(display);
			}

			Lib.current.stage.focus = null;
			display = null;
		}

		if (ready)
		{
			#if lime
			if (!complete)
			{
