			quadraticCurveTo(scaledRight, scaledBottom, scaledRightX, scaledBottom);
			cairo.lineTo(scaledLeftX, scaledBottom);
			quadraticCurveTo(scaledLeft, scaledBottom, scaledLeft, scaledBottomY);
