		advance();
		prev = DRAW_TRIANGLES;
		return new DrawTrianglesView(this);
	}

	public inline function readEndFill():EndFillView
	{
		advance();
		prev = END_FILL;
		return new EndFillView(this);
	}

	public inline function readLineBitmapStyle():LineBitmapStyleView
