						}

						if (2 < channels)
						{
							color3 += this.noise((px + px_delta_b) * (1.0 / _scale_x) * frequency, (py + py_delta_b) * (1.0 / _scale_y) * frequency,
								0.0) * persistence;
						}
					}
				}

				var color:Int = 0;

				if (grayscale)
				{
					color = this.color(color1, color1, color1);
