	}

	public override function toString():String
	{
		return __formatToString("AccelerometerEvent", [
			"type",
			"bubbles",
			"cancelable",
			"timestamp",
			"accelerationX",
			"accelerationY",
			"accelerationZ"
		]);
	}

	@:noCompletion private override function __init():Void
	{
		super.__init();
		timestamp = 0;
		accelerationX = 0;
		accelerationY = 0;
		accelerationZ = 0;
	}
}
