	}

	@:noCompletion private override function __init():Void
	{
		super.__init();
		data = new ByteArray();
		data.endian = Endian.LITTLE_ENDIAN;
		position = 0.0;
	}

	#if lime_openal
	private function getBufferSize():Int
	{
		var bufferSize:Int = Std.int(data.length / 4 / 2);
		if (bufferSize > 0)
		{
			if (bufferSize >= 2048 && bufferSize <= 8192)
			{
				return bufferSize;
			}
			else
