				while (FileSystem.exists(newPath))
				{
					newPath = newPathWithoutExt + '($i)$ext';
					i++;
				}
		}*/

		try
		{
			if (isDirectory)
			{
				FileSystem.createDirectory(newPath);
				var files:Array<File> = getDirectoryListing();
				for (file in files)
				{
					var newFile = new File(Path.join([newPath, file.name]));
