				__displayObject.__rotationCosine = Math.cos(radians);
			}

			transform.a = a;
			transform.b = b;
			transform.c = c;
			transform.d = d;
			transform.tx = tx;
			transform.ty = ty;

			__displayObject.__setTransformDirty();
		}
