			__indexBufferData = new UInt16Array(6);
			__indexBufferData[0] = 0;
			__indexBufferData[1] = 1;
			__indexBufferData[2] = 2;
			__indexBufferData[3] = 2;
			__indexBufferData[4] = 1;
			__indexBufferData[5] = 3;

