				__serverCertificateStatus = TRUSTED;
			}
			else
			{
				__serverCertificateStatus = INVALID;
				__cleanSocket();
				dispatchEvent(new IOErrorEvent(IOErrorEvent.IO_ERROR, true, false, "Invalid certificate"));
				return;
			}
		}
		#end
		super.this_onEnterFrame(event);
	}
}
