@SuppressWarnings("checkstyle:FieldDocComment") #if (haxe_ver >= 4.0) enum #else @:enum #end abstract SharedObjectFlushStatus(String) from String to String
{
	public var FLUSHED = "flushed";
	public var PENDING = "pending";
}
#end
