				if (r.write[0] == __socket)
				{
					doConnect = true;
				}
				else if (Sys.time() - __timestamp > timeout / 1000)
				{
					doClose = true;
				}
				else
				{
					// try again later
					return;
				}
			}
			catch (e:Dynamic)
			{
				doClose = true;
			}
		}

		var b = new BytesBuffer();
		var bLength = 0;

		if (doConnect)
		{
			try
			{
				var peer = __socket.peer();
				if (peer == null)
				{
					// not connected yet (hxcpp and hl)
					if (Sys.time() - __timestamp > timeout / 1000)
					{
						doClose = true;
					}
					else
					{
						return;
					}
				}
			}
			catch (e:Dynamic)
			{
				// not connected yet (neko)
				if (Sys.time() - __timestamp > timeout / 1000)
				{
					doClose = true;
				}
				else
				{
					return;
				}
			}
		}
		else if (connected)
		{
			try
			{
				var l:Int;

				do
				{
					l = __socket.input.readBytes(__buffer, 0, __buffer.length);

					if (l > 0)
					{
						b.addBytes(__buffer, 0, l);
						bLength += l;
					}
				}
				while (l == __buffer.length);
			}
			catch (e:Eof)
			{
				// We used to ignore this, but I'm not sure why. There may be an edge case where this causes the socket to prematurely close or become unusable.
				doClose = true;
			}
			catch (e:Error)
			{
				switch (e)
				{
					case Error.Blocked:
					case Error.Custom(custom):
						if (custom != Error.Blocked && custom != "EOF")
						{
							doClose = true;
						}
					default:
						doClose = true;
				}
			}
			catch (e:Dynamic)
			{
				doClose = true;
			}
		}

		if (doClose && connected)
		{
			__cleanSocket();

			dispatchEvent(new Event(Event.CLOSE));
		}
		else if (doClose)
		{
			__cleanSocket();

			dispatchEvent(new IOErrorEvent(IOErrorEvent.IO_ERROR, true, false, "Connection failed"));
		}
		else if (doConnect)
		{
			__connected = true;
			dispatchEvent(new Event(Event.CONNECT));
		}

		if (bLength > 0)
		{
			var newData = b.getBytes();

			var rl = __input.length - __input.position;
			if (rl < 0) rl = 0;

			var newInput = Bytes.alloc(rl + newData.length);
			if (rl > 0) newInput.blit(0, __input, __input.position, rl);
			newInput.blit(rl, newData, 0, newData.length);
			__input = newInput;
			__input.endian = __endian;

			dispatchEvent(new ProgressEvent(ProgressEvent.SOCKET_DATA, false, false, newData.length, 0));
		}

		if (__socket != null)
		{
			try
			{
				flush();
			}
			catch (e:IOError)
			{
				dispatchEvent(new IOErrorEvent(IOErrorEvent.IO_ERROR, true, false, e.message));
			}
		}
		#end
	}

	// Get & Set Methods
	@:noCompletion private function get_bytesAvailable():Int
	{
		return __input.bytesAvailable;
	}

	@:noCompletion private function get_bytesPending():Int
	{
		return __output.length;
	}

	@:noCompletion private function get_connected():Bool
	{
		return __connected;
	}

	@:noCompletion private function get_endian():Endian
	{
		return __endian;
	}

	@:noCompletion private function set_endian(value:Endian):Endian
	{
		__endian = value;

		if (__input != null) __input.endian = value;
		if (__output != null) __output.endian = value;

		return __endian;
	}

	#if sys
	@:noCompletion private function get_localAddress():String
	{
		if (__connected)
		{
			return __socket.host().host.host;
		}
		return null;
	}

	@:noCompletion private function get_localPort():Int
	{
		if (__connected)
		{
			return __socket.host().port;
		}
		return 0;
	}

	@:noCompletion private function get_remoteAddress():String
	{
		if (__connected)
		{
			return __socket.peer().host.host;
		}
		return null;
	}

	@:noCompletion private function get_remotePort():Int
	{
		if (__connected)
		{
			return __socket.peer().port;
		}
		return 0;
	}
	#end
}
