	{
		(this : Socket).setBlocking(value);
	}

	public inline function setCA(cert:Certificate):Void
	{
		__requireSSL("setCA", this);

		(this : sys.ssl.Socket).setCA(cert);
	}

	public inline function setCertificate(cert:Certificate, key:Key):Void
