		#end
	}

	@:noCompletion private static inline function __unwindStack():String
	{
		#if ((cpp || neko) && hxtelemetry && !macro)
		return telemetry.unwind_stack();
		#else
		return "";
		#end
	}

	// Get & Set Methods
	@:noCompletion private static function get_connected():Bool
