package openfl.security;

#if !flash
/**
	The `CertificateStatus` class defines constants used to report the results of
	certificate validation processing by a `SecureSocket` object.

	@see `openfl.net.SecureSocket`
	@see `openfl.net.SecureSocket.serverCertificateStatus`
**/
#if (haxe_ver >= 4.0) enum #else @:enum #end abstract CertificateStatus(String) from String to String
{
	/**
		The certificate is outside its valid period.

		Indicates that certificate validation processing was attempted, but
		failed because the validity period of the certificate is either before
		or after the current date. On some operating systems, the `notYetValid`
		status is reported when the current date is before the validity period
		of the cerificate. On other operating systems, the `expired` status is
		reported in both cases.
	**/
	public var EXPIRED = "expired";

	/**
		An invalid certificate.

		Indicates that certificate validation processing was attempted, but
		failed. This is the generic faliure status that is reported when a more
		specific certificate status cannot be determined.
	**/
	public var INVALID = "invalid";

	/**
		A root or intermediate certificate in this certificate's chain is
		invalid.

		Indicates that certificate validation processing was attempted, but
		failed because the certificate's trust chain was invalid.
	**/
	public var INVALID_CHAIN = "invalidChain";

	/**
		The certificate is not yet valid.

		Indicates that a certificate is not yet valid. The current date is
		before the notBefore date/time of the certificate.
	**/
	public var NOT_YET_VALID = "notYetValid";

	/**
		The certificate common name does not match the expected host name.

		Indicates that certificate validation processing was attempted, but
		failed because the certificate's common name does not match the fully
		qualified domain name of the host.
	**/
	public var PRINCIPAL_MISMATCH = "principalMismatch";

	/**
		The certificate has been revoked.

		Indicates that certificate validation processing was attempted, but
		failed because the certificate has been revoked. On some operating
		systems, the `revoked` status is also reported when the certificate (or
		its root certificate) has been added to the list of untrusted
		certificates on the client computer.
	**/
	public var REVOKED = "revoked";

	/**
		A valid, trusted certificate.

		Indicates that a certificate has not expired, has not failed a
		revocation check, and chains to a trusted root certificate.
	**/
	public var TRUSTED = "trusted";

	/**
		The validity of the certificate is not known.

		Indicates that certificate validation processing has not been performed
		yet on a certificate.
	**/
	public var UNKNOWN = "unknown";

	/**
		The certificate does not chain to a trusted root certificate.

		Indicates that certificate validation processing was attempted, but that
		the certificate does not chain to any of the root certificates in the
		client trust store. On some operating systems, the `untrustedSigners`
		status is also reported if the certificate is in the list of untrusted
		certificates on the client computer.
	**/
	public var UNTRUSTED_SIGNERS = "untrustedSigners";
}
#else
typedef CertificateStatus = flash.security.CertificateStatus;
#end

files.openfl/security/X500DistinguishedName.hx:
package openfl.security;

#if !flash
/**
	The X500DistinguishedName class defines Distinguished Name (DN) properties
	for use in the X509Certificate class. The Distinguished Name protocol is
	specified in [RFC1779](http://tools.ietf.org/rfc/rfc1779).

	This class is useful for any code that needs to examine a server
	certificate's Subject and Issuer DN after a secure socket connection has
	been established. Subject and Issuer DN data is accessible in the
	X509Certificate class's `subject` and `issuer` properties. These properties
	are populated with X500DistinguishedName objects after
	`SecureSocket.connect()` establishes a connection with the server.

	This class stores DN attributes as string properties. You can use the
	`toString()` method to get all of the individual DN properties in one
	string. Properties with no DN value are set to `null`.

	Note: The X500DistinguishedName properties store only the first occurrence
	of each DN attribute, although the DN protocol allows for multiple
	attributes of the same type.

	@see `openfl.net.SecureSocket`
**/
class X500DistinguishedName
{
	private function new() {}

	/**
		Returns the DN CommonName attribute.
	**/
	public var commonName(default, null):String;

	/**
		Returns the DN CountryName attribute.
	**/
	public var countryName(default, null):String;

	/**
		Returns the DN LocalityName attribute.
	**/
	public var localityName(default, null):String;

	/**
		Returns the DN OrganizationalUnitName attribute.
	**/
	public var organizationalUnitName(default, null):String;

	/**
		Returns the DN OrganizationName attribute.
	**/
	public var organizationName(default, null):String;

	/**
		Returns the DN StateOrProvinceName attribute.
	**/
	public var stateOrProvinceName(default, null):String;

	/**
		Returns all DN properties in one string.
	**/
	public function toString():String
	{
		var result = "";
		if (commonName != null)
		{
			result += '/CN=$commonName';
		}
		if (countryName != null)
		{
			result += '/C=$countryName';
		}
		if (localityName != null)
		{
			result += '/L=$localityName';
		}
		if (organizationalUnitName != null)
		{
			result += '/OU=$organizationalUnitName';
		}
		if (organizationName != null)
		{
			result += '/O=$organizationName';
		}
		if (stateOrProvinceName != null)
		{
			result += '/S=$stateOrProvinceName';
		}
		return result;
	}
}
#else
typedef X500DistinguishedName = flash.security.X500DistinguishedName;
#end

files.openfl/security/X509Certificate.hx:
package openfl.security;

import openfl.utils.ByteArray;

#if !flash
/**
	The X509Certificate class represents an X.509 certificate. This class
	defines X.509 properties specified in
	[RFC2459](http://tools.ietf.org/rfc/rfc2459). After you make a successful
	call to `SecureSocket.connect()`, the server's certificate data is stored as
	an X509Certificate instance in the `SecureSocket.serverCertificate`
	property.

	Use this class to examine a server certificate after establishing a secure
	socket connection. The properties in this class provide access to the most
	used attributes of an X.509 certificate. If you must access other parts of a
	server certificate (for example, its extensions), the complete certificate
	is available in the `encoded` property. The certificate stored in the
	`encoded` property is DER-encoded.

	@see `openfl.net.SecureSocket`
**/
class X509Certificate
{
	private function new() {}

	/**
		Provides the whole certificate in encoded form. Client code can decode
		this value to process certificate extensions. X.509 certificate
		extensions are not represented in the other properties in this class.
		Decoding the `encoded` property is the only way to access a
		certificate's extensions.
	**/
	public var encoded(default, null):ByteArray;

	/**
		Provides the issuer's Distinguished Name (DN).
	**/
	public var issuer(default, null):X500DistinguishedName;

	/**
		Provides the issuer's unique identifier.
	**/
	public var issuerUniqueID(default, null):String;

	/**
		Provides the serial number of the certificate as a hexadecimal string.
		The issuer assigns this number, and the number is unique within the
		issuer's list of issued certificates.
	**/
	public var serialNumber(default, null):String;

	/**
		Provides the signature algorithm Object Identifier (OID).
	**/
	public var signatureAlgorithmOID(default, null):String;

	/**
		Provides the signature algorithm's parameters. If there are no signature
		algorithm parameters, this value is set to `null`.
	**/
	public var signatureAlgorithmParams(default, null):ByteArray;

	/**
		Provides the subject's Distinguished Name (DN).
	**/
	public var subject(default, null):X500DistinguishedName;

	/**
		Provides the subject's public key.
	**/
	public var subjectPublicKey(default, null):String;

	/**
		Provides the algorithm OID for the subject's public key.
	**/
	public var subjectPublicKeyAlgorithmOID(default, null):String;

	/**
		Provides the subject's unique identifier.
	**/
	public var subjectUniqueID(default, null):String;

	/**
		Indicates the date on which the certificate's validity period ends.
	**/
	public var validNotAfter(default, null):Date;

	/**
		Indicates the date on which the certificate's validity period begins.
	**/
	public var validNotBefore(default, null):Date;

	/**
		Provides the version number of the certificate format. This property
		indicates whether the certificate has extensions, a unique identifier,
		or only the basic fields.

		- `version` = 2: Indicates X.509 Version 3 - Extensions are present
		- `version` = 1: Indicates X.509 Version 2 - Extensions are not present, but a unique identifier is present.
		- `version` = null: Indicates X.509 Version 1 - Only the basic certificate fields are present
	**/
	public var version(default, null):UInt;
}
#else
typedef X509Certificate = flash.security.X509Certificate;
#end

