package openfl.utils;

#if !flash
import openfl.net.ObjectEncoding;

/**
	The IDataOutput interface provides a set of methods for writing binary data. This
	interface is the I/O counterpart to the IDataInput interface, which reads binary data. The IDataOutput interface is implemented by the FileStream, Socket and ByteArray
	classes.

	All IDataInput and IDataOutput operations are "bigEndian" by default (the most
	significant byte in the sequence is stored at the lowest or first storage address),
	and are nonblocking.

	Sign extension matters only when you read data, not when you write it. Therefore, you
	do not need separate write methods to work with `IDataInput.readUnsignedByte()` and `IDataInput.readUnsignedShort()`. In other words:

	* Use `IDataOutput.writeByte()` with `IDataInput.readUnsignedByte()` and
	`IDataInput.readByte()`.
	* Use `IDataOutput.writeShort()` with `IDataInput.readUnsignedShort()` and
	`IDataInput.readShort()`.
**/
interface IDataOutput
{
	/**
		The byte order for the data, either the `BIG_ENDIAN` or `LITTLE_ENDIAN` constant
		from the Endian class.
	**/
	public var endian(get, set):Endian;

	/**
		Used to determine whether the `AMF3` or `AMF0` format is used when writing or
		reading binary data using the `writeObject()` method. The value is a constant from
		the ObjectEncoding class.
	**/
	public var objectEncoding:ObjectEncoding;

	/**
		Writes a Boolean value. A single byte is written according to the `value` parameter,
		either 1 if `true` or 0 if `false`.

		@param	value	A Boolean value determining which byte is written. If the parameter
		is `true`, 1 is written; if `false`, 0 is written.
	**/
	public function writeBoolean(value:Bool):Void;

	/**
		Writes a byte. The low 8 bits of the parameter are used; the high 24 bits are
		ignored.

		@param	value	A byte value as an integer.
	**/
	public function writeByte(value:Int):Void;

	/**
		Writes a sequence of bytes from the specified byte array, bytes, starting at the
		byte specified by `offset` (using a zero-based index) with a length specified by
		`length`, into the file stream, byte stream, or byte array.

		If the `length` parameter is omitted, the default length of 0 is used and the
		entire buffer starting at `offset` is written. If the `offset` parameter is also
		omitted, the entire buffer is written.

		If the `offset` or `length` parameter is out of range, they are clamped to the
		beginning and end of the bytes array.

		@param	bytes	The byte array to write.
		@param	offset	A zero-based index specifying the position into the array to begin
		writing.
		@param	length	An unsigned integer specifying how far into the buffer to write.
	**/
	public function writeBytes(bytes:ByteArray, offset:Int = 0, length:Int = 0):Void;

	/**
		Writes an IEEE 754 double-precision (64-bit) floating point number.

		@param	value	A double-precision (64-bit) floating point number.
	**/
	public function writeDouble(value:Float):Void;

	/**
		Writes an IEEE 754 single-precision (32-bit) floating point number.

		@param	value	A single-precision (32-bit) floating point number.
	**/
	public function writeFloat(value:Float):Void;

	/**
		Writes a 32-bit signed integer.

		@param	value	A byte value as a signed integer.
	**/
	public function writeInt(value:Int):Void;

	/**
		Writes a multibyte string to the file stream, byte stream, or byte array, using
		the specified character set.

		@param	value	The string value to be written.
		@param	charSet	The string denoting the character set to use. Possible character
		set strings include "shift-jis", "cn-gb", "iso-8859-1", and others. For a complete
		list, see Supported Character Sets.
	**/
	public function writeMultiByte(value:String, charSet:String):Void;

	/**
		Writes an object to the file stream, byte stream, or byte array, in AMF
		serialized format.

		@param	object	The object to be serialized.
	**/
	public function writeObject(object:Dynamic):Void;

	/**
		Writes a 16-bit integer. The low 16 bits of the parameter are used; the high 16
		bits are ignored.

		@param	value	A byte value as an integer.
	**/
	public function writeShort(value:Int):Void;

	/**
		Writes a 32-bit unsigned integer.

		@param	value	A byte value as an unsigned integer.
	**/
	public function writeUnsignedInt(value:Int):Void;

	/**
		Writes a UTF-8 string to the file stream, byte stream, or byte array. The length
		of the UTF-8 string in bytes is written first, as a 16-bit integer, followed by
		the bytes representing the characters of the string.

		@param	value	The string value to be written.
		@throws	RangeError	If the `length` is larger than 65535.
	**/
	public function writeUTF(value:String):Void;

	/**
		Writes a UTF-8 string. Similar to `writeUTF()`, but does not prefix the string with
		a 16-bit `length` word.

		@param	value	The string value to be written.
	**/
	public function writeUTFBytes(value:String):Void;
}
#else
typedef IDataOutput = flash.utils.IDataOutput;
#end

files.openfl/utils/IExternalizable.hx:
package openfl.utils;

#if !flash
/**
	The IExternalizable interface provides control over serialization of a class as it is
	encoded into a data stream. The `writeExternal()` and `readExternal()` methods of the
	IExternalizable interface are implemented by a class to allow customization of the
	contents and format of the data stream (but not the classname or type) for an object
	and its supertypes. Each individual class must serialize and reconstruct the state of
	its instances. These methods must be symmetrical with the supertype to save its state.
	These methods supercede the native Action Message Format (AMF) serialization behavior.

	If a class does not implement, nor inherits from a class which implements, the
	IExternalizable interface, then an instance of the class will be serialized using the
	default mechanism of public members only. As a result, private, internal, and protected
	members of a class will not be available.

	To serialize private members, a class must use the IExternalizable interface. For
	example, the following class will not serialize any of its members because they are
	private:

	```haxe
	class Example {

		private var one:Int;
		private var two:Int;
	}
	```

	However, if you implement the IExternalizable interface, you can write to, and read
	from, the data stream the private members of the class as follows:

	```haxe
	class Example implement IExternalizable {

		private var one:Int;
		private var two:Int;

		public function writeExternal(output:IDataOutput):Void {

			output.writeInt(one);
			output.writeInt(two);
		}

		public function readExternal(input:IDataInput):Void {

			one = input.readInt();
			two = input.readInt();
		}
	}
	```

	**Note:** If a class implements IExternalizable the default serialization no longer
	applies to instances of that class. If that class inherits public members from a super
	class, you must carefully manage those members as well.

	When a subclass of a class implementing IExternalizable has private members of its own,
	the subclass must override the methods of IExternalizable, as follows:

	```haxe
	class Base implements IExternalizable {

		private var one:Boolean;

		public function writeExternal(output:IDataOutput):Void {

			output.writeBoolean(one);
		}

		public function readExternal(input:IDataInput):Void {

			one = input.readBoolean();
		}
	}

	class Example extends Base {

		private var one:String;


		public override function writeExternal(output:IDataOutput):Void {

			super.writeExternal(output);
			output.writeUTF(one);
		}

		public override function readExternal(input:IDataInput):Void {

			super.readExternal(input);
			one = input.readUTF();
		}
	}
	```

	The IExternalizable interface can also be used to compress data before writing it to a
	data stream. For example:

	```haxe
	class Example implements IExternalizable {

		public var one:Bool;
		public var two:Bool;
		public var three:Bool;
		public var four:Bool;
		public var five:Bool;
		public var six:Bool;
		public var seven:Bool;
		public var eight:Bool;

		public function writeExternal(output:IDataOutput):Void {

			var flag:Int = 0;

			if (one) flag |= 1;
			if (two) flag |= 2;
			if (three) flag |= 4;
			if (four) flag |= 8;
			if (five) flag |= 16;
			if (six) flag |= 32;
			if (seven) flag |= 64;
			if (eight) flag |= 128;

			output.writeByte(flag);
		}

		public function readExternal(input:IDataInput):Void {

			var flag:Int = input.readByte();

			one = (flag & 1) != 0;
			two = (flag & 2) != 0;
			three = (flag & 4) != 0;
			four = (flag & 8) != 0;
			five = (flag & 16) != 0;
			six = (flag & 32) != 0;
			seven = (flag & 64) != 0;
			eight = (flag & 128) != 0;
		}
	}
	```
**/
interface IExternalizable
{
	/**
		A class implements this method to decode itself from a data stream by calling the
		methods of the IDataInput interface. This method must read the values in the same
		sequence and with the same types as were written by the `writeExternal()` method.

		@param	input	The name of the class that implements the IDataInput interface.
	**/
	public function readExternal(input:IDataInput):Void;

	/**
		A class implements this method to encode itself for a data stream by calling the
		methods of the IDataOutput interface.

		@param	output	The name of the class that implements the IDataOutput interface.
	**/
	public function writeExternal(output:IDataOutput):Void;
}
#else
typedef IExternalizable = flash.utils.IExternalizable;
#end

