			{
				var fields = Context.getBuildFields();
				var position = Context.currentPos();

				for (field in fields)
				{
					if (field.name == "new")
					{
						var className:String = null;

						for (meta in metaData)
						{
							if (meta.name == ":native" && meta.params.length > 0)
							{
