package openfl.utils._internal.format.amf3;

import haxe.extern.EitherType;
import haxe.io.Bytes;
import openfl.utils._internal.format.amf3.AMF3Value;
import openfl.utils.ByteArray;

typedef Traits =
{
	isExternalizable:Bool,
	isDynamic:Bool,
	className:String, // "" for anonymous
	sealedMemberNames:Array<String>
}

enum AMF3ObjectHeader
{
	HReference(value:AMF3Value);
	HTraits(traits:Traits);
	HExternal(className:String);
}

class AMF3Reader
{
	// reference table for complex objects
	var complexObjectsTable:Array<AMF3Value>; // anonymous objects, typed objects, arrays, dates, xmldocuments, xmls, and bytearrays
	// reference table for object traits
	var objectTraitsTable:Array<Traits>;
	// reference table for strings
	var stringTable:Array<AMF3Value>;
	var i:haxe.io.Input;

	public function new(i:haxe.io.Input, ?parent:AMF3Reader)
	{
		if (parent == null)
		{
			this.complexObjectsTable = [];
			this.objectTraitsTable = [];
			this.stringTable = [];
		}
		else
		{
			this.complexObjectsTable = parent.complexObjectsTable;
			this.objectTraitsTable = parent.objectTraitsTable;
			this.stringTable = parent.stringTable;
		}
		this.i = i;
		i.bigEndian = true;
	}

	function readObject(header:AMF3ObjectHeader = null)
	{
		if (header == null)
		{
			header = readObjectHeader();
		}

		var ret:AMF3Value = null;

		switch (header)
		{
			case HReference(value):
				return value;

			case HExternal(className):
				var o = AMF3Tools.object(AObject(null, null, className));

				if (o != null && #if (haxe_ver >= 4.2) Std.isOfType #else Std.is #end (o, IExternalizable))
				{
					var external:IExternalizable = cast o;
					external.readExternal(new AMF3ReaderInput(this));

					ret = AExternal(external);
				}
				else
				{
					ret = ANull;
				}

			case HTraits(traits):
				var h = new Map();
				ret = AObject(h, null, traits.className != null ? traits.className : null);

				// parse sealed member values
				for (j in 0...traits.sealedMemberNames.length)
					h.set(traits.sealedMemberNames[j], read());

				// parse any dynamic members (name-value pairs) until empty string name is found
				if (traits.isDynamic)
				{
					var s;
					while (true)
					{
						s = AMF3Tools.decode(readString());
						if (s == "") break;
						h.set(s, read());
					}
				}
		}

		// save new object in reference table
		complexObjectsTable.push(ret);

		return ret;
	}

	function readObjectHeader(className:String = null):AMF3ObjectHeader
	{
		var n = readInt(); // get header

		if (n & 1 == 0)
		{
			// object reference
			return HReference(complexObjectsTable[n >> 1]);
		}
		else if (n & 3 == 1)
		{
			// object traits reference
			n >>= 2;
			return HTraits(objectTraitsTable[n]);
		}
		else if (n & 7 == 3)
		{
			// object traits
			var isDynamic = ((n >> 3) & 0x01) == 1;
			var sealedMemberNames:Array<String> = [];
			var count = n >> 4; // the rest of the header is the count of sealed members

			var traits:Traits = {
				isExternalizable: false,
				isDynamic: isDynamic,
				className: className != null ? className : AMF3Tools.decode(readString()),
				sealedMemberNames: sealedMemberNames
			};

			// grab sealed member names from traits section, if any
			for (i in 0...count)
				sealedMemberNames.push(AMF3Tools.decode(readString()));

			objectTraitsTable.push(traits);
			return HTraits(traits);
		}
		else if (n & 7 == 7)
		{
			// externalizable
			return HExternal(className != null ? className : AMF3Tools.decode(readString()));
		}
		else
		{
			throw "Invalid object traits";
		}
	}

	function readMap()
	{
		var n:Int = readInt(); // get header
		if (n & 1 == 0)
		{
			// reference previous array object
			return complexObjectsTable[n >> 1];
		}
		n >>= 1; // the rest of the header is the number of entries in the map
		var h = new Map();
		var ret = AMap(h);
		complexObjectsTable.push(ret);
		i.readByte(); // skip weakKeys
		// var weakKeys = i.readByte() != 0;
		// if( weakKeys )
		//	throw "Dictionary with weakKeys not supported";
		for (i in 0...n)
			h.set(read(), read());
		return ret;
	}

	function readArray()
	{
		var n:Int = readInt(); // get header
		if (n & 1 == 0)
		{
			// reference previous array object
			return complexObjectsTable[n >> 1];
		}
		n >>= 1; // the rest of the header is the dense indexed array length
		var a = new Array();
		var m = new Map<String, AMF3Value>();
		var ret = AArray(a, m);
		complexObjectsTable.push(ret);
		var assocName:String = AMF3Tools.decode(readString());
		while (assocName.length != 0)
		{
			// got associative array element, get value
			m[assocName] = read();

			// next name
			assocName = AMF3Tools.decode(readString());
		}
		for (i in 0...n)
			a.push(read());
		return ret;
	}

	function readIntVector()
	{
		var header:Int = readInt();
		if (header & 1 == 0)
		{
			// reference previous vector object
			return complexObjectsTable[header >> 1];
		}
		var len = header >> 1;
		var fixed = i.readByte() != 0;
		var v = new Vector<Int>(len);
		v.fixed = fixed;

		for (r in 0...len)
		{
			v[r] = i.readInt32();
		}

		var ret = AIntVector(v);

		complexObjectsTable.push(ret);

		return ret;
	}

	function readFloatVector()
	{
		var header:Int = readInt();
		if (header & 1 == 0)
		{
			// reference previous vector object
			return complexObjectsTable[header >> 1];
		}
		var len = header >> 1;
		var fixed = i.readByte() != 0;
		var v = new Vector<Float>(len);
		v.fixed = fixed;

		for (r in 0...len)
		{
			v[r] = i.readDouble();
		}

		var ret = AFloatVector(v);

		complexObjectsTable.push(ret);

		return ret;
	}

	function readObjectVector()
	{
		var header:Int = readInt();
		if (header & 1 == 0)
		{
			// reference previous vector object
			return complexObjectsTable[header >> 1];
		}

		var len = header >> 1;
		var fixed = i.readByte() != 0;
		var className = AMF3Tools.decode(readString());

		var v = new Vector<AMF3Value>(len);
		v.fixed = fixed;

		var ret = AObjectVector(v, className);

		complexObjectsTable.push(ret);

		var header:AMF3ObjectHeader = null;

		for (r in 0...len)
		{
			var code = i.readByte();
			switch (code)
			{
				case 0x01:
					v[r] = null;

				case 0x0a:
					if (header == null)
					{
						header = readObjectHeader(className);
					}
					v[r] = readObject(header);

				default:
					trace("Unhandled object vector code: 0x" + StringTools.hex(code));
			}
		}

		return ret;
	}

	function readByteArray()
	{
		var n = readInt(); // get header
		if (n & 1 == 0)
		{
			// reference previous bytearray object
			return complexObjectsTable[n >> 1];
		}
		n >>= 1; // the rest of the header is the bytearray byte-length
		var b = Bytes.alloc(n);
		for (j in 0...n)
			b.set(j, i.readByte());
		var ba = ByteArray.fromBytes(b);
		ba.endian = BIG_ENDIAN;
		#if (!display && !flash)
		@:privateAccess (ba : ByteArrayData).__amf3Reader = this;
		#end
		var ret = AByteArray(ba);
		complexObjectsTable.push(ret);
		return ret;
	}

	function readInt(signExtend:Bool = false, preShift:Int = 0)
	{
		var c = i.readByte() & 0xFF;
		if (c < 0x80) return c >> preShift;

		var ret:Int = (c & 0x7f) << 7;
		c = i.readByte() & 0xFF;
		if (c < 0x80) return (ret | c) >> preShift;

		ret |= (c & 0x7f);
		ret <<= 7;
		c = i.readByte() & 0xFF;
		if (c < 0x80) return (ret | c) >> preShift;

		ret |= (c & 0x7f);
		ret <<= 8;
		c = i.readByte() & 0xFF;
		ret |= c;

		if (signExtend && (ret & 0x10000000) != 0) ret |= 0xE0000000; // add sign extension

		return ret >> preShift;
	}

	function readString()
	{
		var header = readInt();
		if (header & 1 == 0)
		{
			// get referenced string
			var strRefIdx = header >> 1;
			return stringTable[strRefIdx];
		}
		// now we know this string is a value, next get the length
		var len = header >> 1;
		return readStringNoHeader(len);
	}

	function readStringNoHeader(len:Int)
	{
		if (len == 0) return AString(""); // 0x01 is empty string and is never sent by reference
		// get the string characters
		#if haxe4
		var ret = AString(i.readString(len, UTF8));
		#else
		var u = new haxe.Utf8(len);
		var c = 0, d = 0, j:Int = 0, it = 0;
		while (j < len)
		{
			c = i.readByte();
			if (c < 0x80)
			{
				it = 0;
				d = c;
			}
			else if (c < 0xe0)
			{
				it = 1;
				d = c & 0x1f;
			}
			else if (c < 0xf0)
			{
				it = 2;
				d = c & 0x0f;
			}
			else if (c < 0xf1)
			{
				it = 3;
				d = c & 0x07;
			}
			c = it;
			while (c-- > 0)
			{
				d <<= 6;
				d |= i.readByte() & 0x3f;
			}
			j += it + 1;
			if (d != 0x01)
			{
				u.addChar(d);
			}
		}
		var ret = AString(u.toString());
		#end

		// store the string off for if it gets referenced later
		stringTable.push(ret);
		return ret;
	}

	function readDate()
	{
		var n = readInt(); // get header
		if (n & 1 == 0)
		{
			// reference previous date object
			return complexObjectsTable[n >> 1];
		}
		var date = Date.fromTime(i.readDouble());
		var ret = ADate(date);
		complexObjectsTable.push(ret);
		return ret;
	}

	function readXml()
	{
		var n = readInt(); // get header
		if (n & 1 == 0)
		{
			// reference previous xml object
			return complexObjectsTable[n >> 1];
		}
		n >>= 1; // the rest of the header is the xml string length
		var xml = Xml.parse(AMF3Tools.decode(readStringNoHeader(n)));
		var ret = AXml(xml);
		complexObjectsTable.push(ret);
		return ret;
	}

	public function readWithCode(id:Int)
	{
		var i = this.i;
		return switch (id)
		{
			case 0x00:
				AUndefined;
			case 0x01:
				ANull;
			case 0x02:
				ABool(false);
			case 0x03:
				ABool(true);
			case 0x04:
				AInt(readInt(true));
			case 0x05:
				ANumber(i.readDouble());
			case 0x06:
				readString();
			case 0x07:
				throw "XMLDocument unsupported";
			case 0x08:
				readDate();
			case 0x09:
				readArray();
			case 0x0a:
				readObject();
			case 0x0b:
				readXml();
			case 0x0c:
				readByteArray();
			case 0x0d, 0x0e:
				readIntVector(); // int or uint vector
			case 0x0f:
				readFloatVector();
			case 0x10:
				readObjectVector();
			case 0x11:
				readMap();
			default:
				throw "Unknown AMF " + id;
		}
	}

	public function read()
	{
		var byte = i.readByte();
		return readWithCode(byte);
	}
}

package openfl.utils._internal.format.amf3;

import haxe.io.Input;
import openfl.net.ObjectEncoding;
import openfl.utils._internal.format.amf.AMFReader as AMFReader;
import openfl.utils._internal.format.amf.AMFTools as AMFTools;
import openfl.utils._internal.format.amf.AMFWriter as AMFWriter;
import openfl.utils._internal.format.amf.AMFValue as AMFValue;
import openfl.utils._internal.format.amf3.AMF3Reader as AMF3Reader;
import openfl.utils._internal.format.amf3.AMF3Tools as AMF3Tools;
import openfl.utils._internal.format.amf3.AMF3Value as AMF3Value;
import openfl.utils._internal.format.amf3.AMF3Writer as AMF3Writer;
import openfl.utils.ByteArray;
import openfl.utils.Endian;
import openfl.utils.IDataInput;

@:access(openfl.utils._internal.format.amf3.AMF3Reader)
class AMF3ReaderInput implements IDataInput
{
	#if !flash
	public var bytesAvailable(get, never):UInt;
	public var endian(get, set):Endian;
	public var objectEncoding:ObjectEncoding;
	#else
	#if (haxe_ver < 4.3)
	public var bytesAvailable(default, never):UInt;
	public var endian:Endian;
	public var objectEncoding:ObjectEncoding;
	#else
	@:flash.property public var bytesAvailable(get, never):UInt;
	@:flash.property public var endian(get, set):Endian;
	@:flash.property public var objectEncoding(get, set):ObjectEncoding;
	#end
	#end
	private var i:Input;
	private var r:AMF3Reader;

	public function new(r:AMF3Reader)
	{
		this.i = r.i;
		this.r = r;

		#if flash
		endian = i.bigEndian ? BIG_ENDIAN : LITTLE_ENDIAN;
		#end

		objectEncoding = ObjectEncoding.AMF3;
	}

	public function readBoolean():Bool
	{
		return i.readByte() != 0;
	}

	public function readByte():Int
	{
		return i.readByte();
	}

	public function readBytes(bytes:ByteArray, offset:UInt = 0, length:Int = 0):Void
	{
		i.readBytes(bytes, offset, length);
	}

	public function readDouble():Float
	{
		return i.readDouble();
	}

	public function readFloat():Float
	{
		return i.readFloat();
	}

	public function readInt():Int
	{
		return i.readInt32();
	}

	public function readMultiByte(length:UInt, charSet:String):String
	{
		return i.readString(length);
	}

	public function readObject():Dynamic
	{
		switch (objectEncoding)
		{
			case AMF0:
				var reader = new AMFReader(i);
				var data = AMFTools.unwrapValue(reader.read());
				return data;

			case AMF3:
				var reader = new AMF3Reader(i, r);
				var data = AMF3Tools.decode(reader.read());
				return data;

			default:
				return null;
		}
	}

	public function readShort():Int
	{
		return i.readInt16();
	}

	public function readUnsignedByte():Int
	{
		return i.readByte();
	}

	public function readUnsignedInt():Int
	{
		var ch1 = i.readByte();
		var ch2 = i.readByte();
		var ch3 = i.readByte();
		var ch4 = i.readByte();

		if (endian == LITTLE_ENDIAN)
		{
			return (ch4 << 24) | (ch3 << 16) | (ch2 << 8) | ch1;
		}
		else
		{
			return (ch1 << 24) | (ch2 << 16) | (ch3 << 8) | ch4;
		}
	}

	public function readUnsignedShort():Int
	{
		var ch1 = i.readByte();
		var ch2 = i.readByte();

		if (endian == LITTLE_ENDIAN)
		{
			return (ch2 << 8) + ch1;
		}
		else
		{
			return (ch1 << 8) | ch2;
		}
	}

	public function readUTF():String
	{
		var bytesCount = readUnsignedShort();
		return readUTFBytes(bytesCount);
	}

	public function readUTFBytes(length:Int):String
	{
		return i.readString(length);
	}

	private function get_bytesAvailable():UInt
	{
		return -1;
	}

	private function get_endian():Endian
	{
		return i.bigEndian ? Endian.BIG_ENDIAN : Endian.LITTLE_ENDIAN;
	}

	private function set_endian(value:Endian):Endian
	{
		return value;
	}

	#if flash
	private function get_objectEncoding():ObjectEncoding
	{
		return ObjectEncoding.AMF3;
	}

	private function set_objectEncoding(value:ObjectEncoding):ObjectEncoding
	{
		return value;
	}
	#end
}

